const categories = {
'Movement':['Move your body intentionally every day','Get outside for a walk','Complete a workout','Stretch or do mobility work for 10 minutes','Take the stairs when you can'],
'Nutrition & hydration':['Meet my daily water goal','Eat a protein-rich food at each meal','Add a fruit or vegetable to your meals','Eat meals sitting down, without distractions','Plan your meals for the next day','Make your next food choice a nourishing one'],
'Sleep & recovery':['Aim for 7+ hours of sleep','Create a consistent bedtime','Put your phone away 30 minutes before bed','Take 10 minutes to stretch, breathe, or unwind'],
'Mindset & self-care':['Take 10 minutes just for YOU','Practice gratitude — write down 3 things you’re grateful for','Give yourself grace when things don’t go as planned','Do something that makes you happy','Spend time with someone who makes you feel good','Check in with yourself: How am I feeling today, and what do I need?']};
const defaults={goals:['Get outside for a walk','Eat a protein-rich food at each meal','Take 10 minutes just for YOU'],checks:{},commitment:'3',title:'The 21-day habit challenge',welcome:'You don’t need a perfect day. Start with one small thing you can do for yourself, and build from there.',open:true,custom:[],workouts:[{title:'Full-body foundations',duration:'25',equipment:'Dumbbells · Chair',date:'2026-09-21',plan:'Sample workout for layout review — Kelsey will supply the final plan.\n\nWarm-up\nMain exercises and repetitions\nModifications\nCool-down',demo:'',published:true},{title:'A little movement, a little reset',duration:'15',equipment:'No equipment',date:'2026-09-24',plan:'Sample workout for layout review — Kelsey will supply the final plan.',demo:'',published:true},{title:'Strong at home',duration:'30',equipment:'Dumbbells',date:'2026-09-28',plan:'Sample workout for layout review — Kelsey will supply the final plan.',demo:'',published:false}]};
let state;try{state=JSON.parse(localStorage.getItem('hh-challenge-prototype-v1'))||structuredClone(defaults)}catch{state=structuredClone(defaults)}
let mode='member',view='today',day=7;const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('hh-challenge-prototype-v1',JSON.stringify(state))}catch{toast('Browser storage unavailable. Changes will last until this page closes.')}}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>t.style.display='none',3500)}
function dateLabel(n){return new Date(Date.UTC(2026,8,20+n)).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'})}
const count=n=>(state.checks[n]||[]).filter(Boolean).length;
function heading(tag,title,sub,extra=''){return `<div class="heading"><div><span class="eyebrow">${tag}</span><h1>${esc(title)}</h1><p>${sub}</p></div>${extra}</div>`}
function render(){const nav=mode==='member'?[['today','My challenge'],['join','Choose goals'],['workouts','Workouts'],['community','Community']]:[['overview','Overview'],['setup','Challenge setup'],['goals','Goal options'],['workouts','Workouts'],['people','Participants']];app.innerHTML=`<div class="layout"><nav class="sidebar" aria-label="${mode==='member'?'Participant':'Admin'} sections">${nav.map(([id,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${label}</button>`).join('')}<small>SEPT 21 – OCT 11<br>21 days. Your own pace.</small></nav><main>${mode==='member'?member():admin()}<p class="footer-note">Interactive design preview · Demo date: September 27, 2026 · No real accounts or messages.</p></main></div>`;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));bind()}
function workoutRows(adminMode=false){const rows=state.workouts.map((w,i)=>({w,i})).filter(({w})=>adminMode||w.published&&w.date<='2026-09-27');return rows.map(({w,i},n)=>`<div class="workout"><span class="number">${String(n+1).padStart(2,'0')}</span><div class="details"><h3>${esc(w.title)}</h3><p>${esc(w.duration)} min · ${esc(w.equipment)}</p>${adminMode?`<span class="small">${esc(w.date)} · ${w.published?'Published':'Draft'}</span>`:''}</div><button class="link" data-${adminMode?'edit':'workout'}="${i}">${adminMode?'Edit':'View →'}</button></div>`).join('')||'<p>No workouts published yet. Check back soon.</p>'}
function member(){if(view==='join')return heading('MAKE IT YOURS','Three small promises to yourself.','Choose three habits for this challenge. Keep them realistic for your life.')+`<form id="goals-form"><div class="card"><label class="field">How many workouts can you commit to each week?<select name="commitment">${[1,2,3,4,5].map(n=>`<option ${state.commitment==n?'selected':''}>${n}</option>`).join('')}</select></label><p class="small">This is a separate weekly intention. Rest days count as part of your plan.</p></div>${Object.entries({...categories,'Your own habits':state.custom}).map(([cat,items])=>items.length?`<h3 class="category">${cat}</h3><div class="choices">${items.map(g=>`<label class="choice"><input type="checkbox" name="goal" value="${esc(g)}" ${state.goals.includes(g)?'checked':''}><span>${esc(g)}</span></label>`).join('')}</div>`:'').join('')}<div class="card"><label class="field">Or write a habit that matters to you<input id="custom-goal" maxlength="140" placeholder="For example: Read for 10 minutes"></label><button type="button" class="btn secondary" id="add-custom">Add my habit</button></div><div class="sticky-actions"><span id="selection-count">${state.goals.length} of 3 selected</span><button class="btn" type="submit">Save my three goals →</button></div></form>`;
if(view==='workouts')return heading('AT HOME, ON YOUR TERMS','Your workout library','Written plans and movement demonstrations from Kelsey.')+`<div class="card"><span class="pill">Sample workouts for review</span>${workoutRows()}</div>`;
if(view==='community')return heading('STRONGER TOGETHER','A little encouragement goes a long way.','Share a win, ask a question, and connect with the group.')+`<div class="card aqua"><h2>The challenge community</h2><p>Our recommended first version uses a WhatsApp group, linked right here.</p><button class="btn" id="community">Join the WhatsApp group ↗</button><p class="small" style="margin-top:16px">Preview: Kelsey’s group link hasn’t been added yet.</p></div>`;
return heading('YOUR DAILY MOMENT',`Small habits. Real progress.`,`${esc(state.title)} · September 21 – October 11`,'<span class="pill">Week 1 of 3</span>')+`<div class="grid"><div><section class="card"><div class="topline"><div><span class="eyebrow">${dateLabel(day)} · Day ${day} of 21</span><h2 style="margin-top:8px">Your three daily goals</h2></div><strong>${count(day)}/3</strong></div><div class="progress"><span style="width:${count(day)/3*100}%"></span></div>${state.goals.map((g,i)=>`<label class="goal"><input type="checkbox" data-check="${i}" ${(state.checks[day]||[])[i]?'checked':''}><span>${esc(g)}</span></label>`).join('')}<p class="small" style="margin-top:15px;margin-bottom:0">${count(day)===3?'You showed up for yourself today. That counts.':'Check things off as you go. Every little bit counts.'}</p></section><section class="card"><div class="topline"><h2>This week’s workouts</h2><span class="small">At home</span></div>${workoutRows()}</section></div><aside><section class="card aqua"><span class="eyebrow">A NOTE FROM KELSEY · SAMPLE</span><p class="quote" style="color:var(--ink);margin-top:14px">“${esc(state.welcome)}”</p><strong>Stronger together. Better every day.</strong></section><section class="card"><h3>Your 21 days</h3><p class="small">Tap a past day to fill in your progress.</p><div class="calendar">${Array.from({length:21},(_,i)=>`<button class="day ${day===i+1?'selected':''} ${count(i+1)===3?'done':''}" data-day="${i+1}" ${i+1>7?'disabled':''} aria-label="${dateLabel(i+1)}, ${count(i+1)} of 3 complete">${i+1}</button>`).join('')}</div><p class="small" style="margin-top:15px;margin-bottom:0">${Object.values(state.checks).filter(a=>a.filter(Boolean).length===3).length} days with all three habits complete</p></section><section class="card"><h3>Keep going after October 11</h3><p class="small">Find your next step with Kelsey.</p><button class="link" id="next-step">Explore coaching options →</button></section></aside></div>`}
function admin(){if(view==='workouts')return heading('CHALLENGE CONTENT','Workouts','Build a written plan, add demonstration links, and choose when it appears.','<button class="btn" id="new-workout">+ Add workout</button>')+`<section class="card">${workoutRows(true)}</section>`;
if(view==='setup')return heading('SEPTEMBER CHALLENGE','Make it your own','Control the challenge details and what participants see.')+`<form id="setup-form" class="card"><label class="field">Challenge name<input name="title" value="${esc(state.title)}" required></label><div class="grid"><label class="field">Starts<input type="date" value="2026-09-21" readonly></label><label class="field">Ends<input type="date" value="2026-10-11" readonly></label></div><p class="small">Dates are fixed for this first preview. Late joiners start on the current challenge day.</p><label class="field">Welcome / announcement<textarea name="welcome" required>${esc(state.welcome)}</textarea></label><label class="choice"><input type="checkbox" name="open" ${state.open?'checked':''}> Signup is open, including late arrivals</label><div class="actions" style="margin-top:20px"><button class="btn">Save changes</button><button class="btn secondary" type="button" id="preview-member">Preview participant view</button></div></form>`;
if(view==='goals')return heading('PARTICIPANT CHOICES','A habit for every kind of day','Kelsey’s suggested habits, plus room for a personal goal.')+`<div class="card"><p>Participants choose three daily habits. Their weekly exercise commitment is collected separately.</p><p class="small">For the working version: editing an option will preserve participants’ existing habit history.</p>${Object.entries({...categories,'Custom examples':state.custom}).map(([cat,items])=>`<h3 class="category">${cat}</h3>${items.map(g=>`<div class="workout"><span>${esc(g)}</span></div>`).join('')}`).join('')}<button class="btn secondary" id="admin-add-goal" style="margin-top:20px">+ Add a goal option</button></div>`;
if(view==='people')return heading('PARTICIPATION','People, not perfect streaks','Illustrative records only — no real member information.')+`<div class="card table-wrap"><table><thead><tr><th>Participant</th><th>Joined</th><th>Days completed</th><th>Status</th></tr></thead><tbody><tr><td>Sample participant A</td><td>Sept 21</td><td>5 of 7</td><td>Participating</td></tr><tr><td>Sample participant B</td><td>Sept 24</td><td>2 of 4</td><td>Late arrival</td></tr><tr><td>Your preview</td><td>Sept 21</td><td>${Object.values(state.checks).filter(a=>a.filter(Boolean).length===3).length} of 7</td><td>Demo</td></tr></tbody></table><p class="small" style="margin-top:18px">Days before someone joined are excluded from their progress.</p></div>`;
return heading('KELSEY’S WORKSPACE',state.title,'September 21 – October 11, 2026','<button class="btn secondary" id="preview-member">Preview as participant ↗</button>')+`<div class="stats"><div class="stat"><span class="small">Challenge day</span><strong>7 <span class="small">/ 21</span></strong></div><div class="stat"><span class="small">Workout plans</span><strong>${state.workouts.length}</strong></div><div class="stat"><span class="small">Signup</span><strong style="font-size:24px">${state.open?'Open':'Closed'}</strong></div></div><div class="grid"><div><section class="card"><div class="topline"><h2>Your workout schedule</h2><button class="link" data-view="workouts">Manage →</button></div>${workoutRows(true)}</section><section class="card"><h2>One place for your updates</h2><p>${esc(state.welcome)}</p><button class="link" data-view="setup">Edit welcome & announcement →</button></section></div><aside><section class="card purple"><span class="eyebrow">READY FOR THE NEXT STEP</span><h2 style="margin-top:15px">From small habits to lasting support.</h2><p>After October 11, guide participants toward your six-week in-person session or online personal training.</p><button class="btn white" id="next-step">Preview next steps</button></section><section class="card"><h3>Your challenge checklist</h3><p class="small">✓ 21-day shared calendar<br>✓ Three goals per participant<br>✓ Late arrivals welcome<br>✓ Written workout plans</p><p class="small">Still to supply: final workouts, exercise links, and the WhatsApp group link.</p></section></aside></div>`}
function openModal(html){document.querySelector('#modal-body').innerHTML=html;modal.showModal()}
function editWorkout(i){const w=i<0?{title:'',duration:'',equipment:'',date:'2026-09-28',plan:'',demo:'',published:false}:state.workouts[i];openModal(`<span class="eyebrow">WORKOUT EDITOR</span><h2>${i<0?'Add a workout':'Edit workout'}</h2><form id="workout-form"><label class="field">Title<input name="title" value="${esc(w.title)}" required maxlength="100"></label><div class="grid"><label class="field">Minutes<input name="duration" type="number" min="1" max="180" value="${esc(w.duration)}" required></label><label class="field">Publish date<input name="date" type="date" min="2026-09-21" max="2026-10-11" value="${w.date}" required></label></div><label class="field">Equipment<input name="equipment" value="${esc(w.equipment)}" required></label><label class="field">Written plan<textarea name="plan" required>${esc(w.plan)}</textarea></label><label class="field">Exercise demonstration link<input name="demo" type="url" placeholder="https://www.youtube.com/watch?..." value="${esc(w.demo)}"></label><p class="small">This preview uses one link. The final editor can attach a demonstration to each exercise.</p><label class="choice"><input name="published" type="checkbox" ${w.published?'checked':''}> Publish on the selected date (otherwise save as draft)</label><button class="btn" style="margin-top:20px">Save workout</button></form>`);document.querySelector('#workout-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);const obj=Object.fromEntries(d);if(obj.demo&&!/^https:\/\//i.test(obj.demo)){toast('Use an https link for the exercise demonstration.');return}obj.published=d.has('published');if(i<0)state.workouts.push(obj);else state.workouts[i]=obj;save();modal.close();render();toast('Workout saved in this preview.')}}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=+b.dataset.day;render()});document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{state.checks[day]||=[];state.checks[day][+b.dataset.check]=b.checked;save();render()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editWorkout(+b.dataset.edit));document.querySelectorAll('[data-workout]').forEach(b=>b.onclick=()=>{const w=state.workouts[+b.dataset.workout];openModal(`<span class="eyebrow">AT-HOME WORKOUT · SAMPLE</span><h2>${esc(w.title)}</h2><p>${esc(w.duration)} min · ${esc(w.equipment)}</p><div style="white-space:pre-wrap">${esc(w.plan)}</div>${w.demo&&/^https:\/\//i.test(w.demo)?`<a class="btn" style="margin-top:20px" href="${esc(w.demo)}" target="_blank" rel="noopener noreferrer">Watch exercise demonstration ↗</a>`:'<p class="small" style="margin-top:20px">Exercise demonstration links will appear here once Kelsey adds them.</p>'}`)});
const on=(id,fn)=>{const el=document.getElementById(id);if(el)el.onclick=fn};on('new-workout',()=>editWorkout(-1));on('preview-member',()=>{mode='member';view='today';render()});on('community',()=>toast('Kelsey’s WhatsApp group link will be connected before launch.'));on('next-step',()=>openModal('<span class="eyebrow">AFTER THE CHALLENGE</span><h2>Keep building on what you started.</h2><p>Choose the support that fits your next chapter.</p><section class="card"><h3>Six-week in-person session</h3><p>Keep showing up with Kelsey and the group.</p><span class="small">The final version will link to session registration.</span></section><section class="card"><h3>Online personal training</h3><p>A personal plan with coaching that fits your week.</p><span class="small">The final version will link to online training signup.</span></section>'));
on('admin-add-goal',()=>{openModal('<h2>Add a goal option</h2><form id="option-form"><label class="field">Daily habit<input name="goal" required maxlength="140"></label><button class="btn">Add goal</button></form>');document.querySelector('#option-form').onsubmit=e=>{e.preventDefault();const g=new FormData(e.target).get('goal').trim();if(g&&!state.custom.includes(g)){state.custom.push(g);save()}modal.close();render()}});
const setup=document.querySelector('#setup-form');if(setup)setup.onsubmit=e=>{e.preventDefault();const d=new FormData(setup);state.title=d.get('title').trim();state.welcome=d.get('welcome').trim();state.open=d.has('open');save();render();toast('Challenge changes saved in this preview.')};
const form=document.querySelector('#goals-form');if(form){const update=()=>{const n=form.querySelectorAll('[name="goal"]:checked').length;document.querySelector('#selection-count').textContent=`${n} of 3 selected`;form.querySelector('[type="submit"]').disabled=n!==3};form.onchange=update;update();form.onsubmit=e=>{e.preventDefault();const d=new FormData(form);const gs=d.getAll('goal');if(gs.length!==3)return;const changed=JSON.stringify(gs)!==JSON.stringify(state.goals);if(changed&&Object.keys(state.checks).length){toast('Goals are locked after tracking begins. This protects your existing progress.');return}state.goals=gs;state.commitment=d.get('commitment');save();view='today';render();toast('Your three goals are ready.')};on('add-custom',()=>{const input=document.querySelector('#custom-goal'),g=input.value.trim();if(!g)return;if(!state.custom.includes(g)&&!Object.values(categories).flat().includes(g)){state.custom.push(g);save()}const selected=[...form.querySelectorAll('[name="goal"]:checked')].map(x=>x.value);render();document.querySelectorAll('[name="goal"]').forEach(el=>el.checked=selected.includes(el.value));document.querySelector('#goals-form').dispatchEvent(new Event('change'));toast('Habit added. Select it as one of your three goals.')})}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;view=mode==='member'?'today':'overview';render()});document.querySelector('.close').onclick=()=>modal.close();render();
